// Package ocsf is ConfigBridge's common schema: every stored record is an OCSF
// event of one of the classes in schema.json (a pinned, trimmed copy of the
// official OCSF schema, generated by scripts/ocsf_subset.py).
//
// It answers four questions, all from the official schema, never hand-written lists:
//   - Resolve: is "vulnerabilities.0.cve.uid" a real, mappable field, and of what type?
//   - Coerce: turn a mapped vendor value into that field's OCSF type (or refuse it)
//   - Build: assemble the event, filling the fields the platform owns
//   - Validate: types, enums and required attributes of every present object
package ocsf

import (
	_ "embed"
	"encoding/json"
	"errors"
	"fmt"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"
)

//go:embed schema.json
var schemaJSON []byte

// Attr is one OCSF attribute.
type Attr struct {
	Type        string            `json:"type"`
	ObjectType  string            `json:"object_type"`
	IsArray     bool              `json:"is_array"`
	Requirement string            `json:"requirement"`
	Enum        map[string]string `json:"enum"` // value -> caption
}

// Class is one OCSF event class.
type Class struct {
	Name         string          `json:"-"`
	UID          int             `json:"uid"`
	Caption      string          `json:"caption"`
	CategoryUID  int             `json:"category_uid"`
	CategoryName string          `json:"category_name"`
	Attributes   map[string]Attr `json:"attributes"`
}

type object struct {
	Attributes map[string]Attr `json:"attributes"`
}

var schema struct {
	Version string            `json:"version"`
	Types   map[string]string `json:"types"` // type -> base type
	Classes map[string]*Class `json:"classes"`
	Objects map[string]object `json:"objects"`
}

func init() {
	if err := json.Unmarshal(schemaJSON, &schema); err != nil {
		panic("ocsf: embedded schema is invalid: " + err.Error())
	}
	for name, c := range schema.Classes {
		c.Name = name
	}
}

// Version is the pinned OCSF schema version written into metadata.version.
func Version() string { return schema.Version }

// Identity is the field that identifies one record per source; it becomes the
// upsert key, so re-running a source updates rows instead of duplicating them.
var Identity = map[string]string{
	"vulnerability_finding": "finding_info.uid",
	"detection_finding":     "finding_info.uid",
	"user_inventory":        "user.uid",
	"inventory_info":        "device.uid",
	"authentication":        "metadata.uid",
}

// defaultActivity: findings are "Create", inventory snapshots are "Collect".
var defaultActivity = map[string]int{
	"vulnerability_finding": 1, "detection_finding": 1,
	"user_inventory": 2, "inventory_info": 2, "authentication": 1,
}

// Lookup returns a supported class by name (e.g. "vulnerability_finding").
func Lookup(name string) (*Class, bool) {
	c, ok := schema.Classes[name]
	return c, ok
}

// ObjectAttributes returns an OCSF object's attributes (empty = free-form).
func ObjectAttributes(name string) map[string]Attr { return schema.Objects[name].Attributes }

// Classes lists the supported class names.
func Classes() []string {
	out := make([]string, 0, len(schema.Classes))
	for name := range schema.Classes {
		out = append(out, name)
	}
	sort.Strings(out)
	return out
}

// PlatformOwned fields are set by ConfigBridge and can never be mapped by a config:
// identity of the class, provenance (tenant, source, time we processed it) and
// the raw vendor payload, which we deliberately never store.
var PlatformOwned = map[string]bool{
	"class_uid": true, "class_name": true, "category_uid": true, "category_name": true,
	"activity_id": true, "activity_name": true, "type_uid": true, "type_name": true, "severity": true,
	"metadata.version": true, "metadata.tenant_uid": true, "metadata.source": true, "metadata.processed_time": true,
	"raw_data": true, "raw_data_hash": true, "raw_data_size": true,
}

var freeKey = regexp.MustCompile(`^[a-z][a-z0-9_]{0,63}$`)

const maxDepth = 8
const maxIndex = 9

// Resolve checks that path is a mappable scalar field of class and returns it.
// Arrays need an explicit index ("vulnerabilities.0.cve.uid"). Objects without
// a defined shape in OCSF (e.g. "unmapped") accept any lower-case keys.
func Resolve(c *Class, path string) (Attr, error) {
	segs := strings.Split(path, ".")
	if path == "" || len(segs) > maxDepth {
		return Attr{}, errors.New("path must have 1-8 segments")
	}
	if PlatformOwned[path] {
		return Attr{}, errors.New("set by the platform")
	}
	attrs := c.Attributes
	for i := 0; i < len(segs); i++ {
		seg := segs[i]
		if attrs == nil { // free-form object: any key, scalar value
			if !freeKey.MatchString(seg) {
				return Attr{}, errors.New("free-form keys must be lower-case identifiers")
			}
			if i != len(segs)-1 {
				return Attr{}, errors.New("free-form values must be scalars")
			}
			return Attr{Type: "json_t"}, nil
		}
		a, ok := attrs[seg]
		if !ok {
			return Attr{}, fmt.Errorf("%q is not an OCSF attribute here", seg)
		}
		if a.IsArray {
			if i+1 >= len(segs) {
				return Attr{}, errors.New("arrays need an index, e.g. .0")
			}
			n, err := strconv.Atoi(segs[i+1])
			if err != nil || n < 0 || n > maxIndex {
				return Attr{}, errors.New("array index must be 0-9")
			}
			i++
		}
		if a.Type != "object_t" {
			if i != len(segs)-1 {
				return Attr{}, fmt.Errorf("%q is a scalar", seg)
			}
			return a, nil
		}
		if i == len(segs)-1 {
			return Attr{}, fmt.Errorf("%q is an object; map a field inside it", seg)
		}
		attrs = schema.Objects[a.ObjectType].Attributes
		if len(attrs) == 0 {
			attrs = nil
		}
	}
	return Attr{}, errors.New("invalid path")
}

func base(t string) string {
	if t == "timestamp_t" || t == "datetime_t" {
		return t
	}
	if b, ok := schema.Types[t]; ok && b != "" {
		return b
	}
	return t
}

// Coerce converts v to the OCSF type of a. Strings are accepted for numbers and
// booleans ("4" -> 4, "true" -> true) so lookups can produce enum IDs.
func Coerce(a Attr, v any) (any, error) {
	var out any
	switch base(a.Type) {
	case "timestamp_t":
		switch x := v.(type) {
		case time.Time:
			out = x.UnixMilli()
		default:
			n, err := toInt(v)
			if err != nil {
				return nil, errors.New("timestamp needs the datetime transform or epoch milliseconds")
			}
			out = n
		}
	case "datetime_t":
		switch x := v.(type) {
		case time.Time:
			out = x.UTC().Format(time.RFC3339Nano)
		case string:
			out = x
		default:
			return nil, errors.New("datetime must be a string")
		}
	case "string_t":
		switch x := v.(type) {
		case string:
			out = x
		case bool, float64, int, int64, json.Number:
			out = fmt.Sprint(x)
		case time.Time:
			out = x.UTC().Format(time.RFC3339Nano)
		default:
			return nil, errors.New("string required")
		}
		if len(out.(string)) > 65536 {
			return nil, errors.New("string longer than 64 KB")
		}
	case "integer_t", "long_t":
		n, err := toInt(v)
		if err != nil {
			return nil, errors.New("integer required")
		}
		out = n
	case "float_t":
		f, err := strconv.ParseFloat(fmt.Sprint(v), 64)
		if err != nil {
			return nil, errors.New("number required")
		}
		out = f
	case "boolean_t":
		switch x := v.(type) {
		case bool:
			out = x
		case string:
			b, err := strconv.ParseBool(x)
			if err != nil {
				return nil, errors.New("boolean required")
			}
			out = b
		default:
			return nil, errors.New("boolean required")
		}
	case "json_t":
		switch v.(type) {
		case string, bool, float64, int, int64, json.Number:
			out = v
		case time.Time:
			out = v.(time.Time).UTC().Format(time.RFC3339Nano)
		default:
			return nil, errors.New("scalar required")
		}
	default:
		return nil, fmt.Errorf("unsupported OCSF type %s", a.Type)
	}
	if a.Enum != nil {
		if _, ok := a.Enum[fmt.Sprint(out)]; !ok {
			return nil, errors.New("value is not in the OCSF enum")
		}
	}
	return out, nil
}

func toInt(v any) (int64, error) {
	switch x := v.(type) {
	case int64:
		return x, nil
	case int:
		return int64(x), nil
	case float64:
		if x != float64(int64(x)) {
			return 0, errors.New("not an integer")
		}
		return int64(x), nil
	}
	return strconv.ParseInt(strings.TrimSpace(fmt.Sprint(v)), 10, 64)
}

// Set writes v at path, creating objects and array elements on the way.
func Set(doc map[string]any, path string, v any) {
	segs := strings.Split(path, ".")
	var cur any = doc
	for i, seg := range segs {
		last := i == len(segs)-1
		next := func() any {
			if _, err := strconv.Atoi(segs[i+1]); err == nil {
				return []any{}
			}
			return map[string]any{}
		}
		switch c := cur.(type) {
		case map[string]any:
			if last {
				c[seg] = v
				return
			}
			if c[seg] == nil {
				c[seg] = next()
			}
			cur = c[seg]
			// arrays are replaced by a grown copy, so re-read through the parent
			if arr, ok := cur.([]any); ok {
				n, _ := strconv.Atoi(segs[i+1])
				for len(arr) <= n {
					arr = append(arr, nil)
				}
				c[seg] = arr
				cur = arr
			}
		case []any:
			n, _ := strconv.Atoi(seg)
			if last {
				c[n] = v
				return
			}
			if c[n] == nil {
				c[n] = next()
			}
			cur = c[n]
			if arr, ok := cur.([]any); ok {
				m, _ := strconv.Atoi(segs[i+1])
				for len(arr) <= m {
					arr = append(arr, nil)
				}
				c[n] = arr
				cur = arr
			}
		}
	}
}

// Get reads the value at path, or nil.
func Get(doc map[string]any, path string) any {
	var cur any = doc
	for _, seg := range strings.Split(path, ".") {
		switch c := cur.(type) {
		case map[string]any:
			cur = c[seg]
		case []any:
			n, err := strconv.Atoi(seg)
			if err != nil || n < 0 || n >= len(c) {
				return nil
			}
			cur = c[n]
		default:
			return nil
		}
	}
	return cur
}

// Context is what the platform knows about a record that the vendor does not.
type Context struct {
	Tenant     string    // metadata.tenant_uid
	Source     string    // metadata.source: the connector id
	Product    string    // default metadata.product.name when the config doesn't map one
	Fetched    time.Time // metadata.processed_time, and time when not mapped
	ActivityID int       // 0 = class default
}

// FieldError says which OCSF field is wrong. Messages never contain values.
type FieldError struct{ Field, Reason string }

func (e *FieldError) Error() string { return e.Field + ": " + e.Reason }

// Build assembles one OCSF event from already-coerced mapped values (path -> value)
// and validates it against the schema.
func Build(c *Class, mapped map[string]any, ctx Context) (map[string]any, error) {
	doc := map[string]any{}
	paths := make([]string, 0, len(mapped))
	for p := range mapped {
		paths = append(paths, p)
	}
	sort.Strings(paths)
	for _, p := range paths {
		Set(doc, p, mapped[p])
	}
	act := ctx.ActivityID
	if act == 0 {
		act = defaultActivity[c.Name]
	}
	actName := c.Attributes["activity_id"].Enum[strconv.Itoa(act)]
	if actName == "" {
		return nil, &FieldError{"activity_id", "not in the class enum"}
	}
	doc["class_uid"], doc["class_name"] = c.UID, c.Caption
	doc["category_uid"], doc["category_name"] = c.CategoryUID, c.CategoryName
	doc["activity_id"], doc["activity_name"] = act, actName
	doc["type_uid"], doc["type_name"] = c.UID*100+act, c.Caption+": "+actName
	if doc["severity_id"] == nil {
		doc["severity_id"] = int64(0)
	}
	doc["severity"] = c.Attributes["severity_id"].Enum[fmt.Sprint(doc["severity_id"])]
	if doc["time"] == nil {
		doc["time"] = ctx.Fetched.UnixMilli()
	}
	meta, _ := doc["metadata"].(map[string]any)
	if meta == nil {
		meta = map[string]any{}
		doc["metadata"] = meta
	}
	meta["version"] = schema.Version
	meta["tenant_uid"] = ctx.Tenant
	meta["source"] = ctx.Source
	meta["processed_time"] = ctx.Fetched.UnixMilli()
	if meta["product"] == nil {
		meta["product"] = map[string]any{"name": ctx.Product}
	}
	if err := Validate(c, doc); err != nil {
		return nil, err
	}
	return doc, nil
}

// Validate checks doc against the class: known attributes only, correct types,
// enum values, and required attributes of the class and of every present object.
func Validate(c *Class, doc map[string]any) error {
	return validateObject(c.Attributes, doc, "")
}

func validateObject(attrs map[string]Attr, m map[string]any, prefix string) error {
	for name, a := range attrs {
		if a.Requirement == "required" && m[name] == nil {
			return &FieldError{prefix + name, "required by OCSF"}
		}
	}
	for name, v := range m {
		a, ok := attrs[name]
		if !ok {
			return &FieldError{prefix + name, "not an OCSF attribute"}
		}
		if v == nil {
			continue
		}
		if a.IsArray {
			arr, ok := v.([]any)
			if !ok {
				return &FieldError{prefix + name, "must be an array"}
			}
			for i, el := range arr {
				if el == nil {
					return &FieldError{fmt.Sprintf("%s%s.%d", prefix, name, i), "array element missing (indexes must start at 0 with no gaps)"}
				}
				if err := validateValue(a, el, fmt.Sprintf("%s%s.%d", prefix, name, i)); err != nil {
					return err
				}
			}
			continue
		}
		if err := validateValue(a, v, prefix+name); err != nil {
			return err
		}
	}
	return nil
}

func validateValue(a Attr, v any, path string) error {
	if a.Type == "object_t" {
		m, ok := v.(map[string]any)
		if !ok {
			return &FieldError{path, "must be an object"}
		}
		attrs := schema.Objects[a.ObjectType].Attributes
		if len(attrs) == 0 { // free-form (e.g. unmapped): scalars only
			for k, x := range m {
				switch x.(type) {
				case string, bool, float64, int, int64, json.Number, nil:
				default:
					return &FieldError{path + "." + k, "free-form values must be scalars"}
				}
			}
			return nil
		}
		return validateObject(attrs, m, path+".")
	}
	if _, err := Coerce(a, v); err != nil {
		return &FieldError{path, err.Error()}
	}
	return nil
}
